+      await file.sync();
+    } finally {
+      await file.close();
+    }
+    await rename(temporaryPath, databasePath);
+    temporaryCreated = false;
+  } finally {
+    if (temporaryCreated) await unlink(temporaryPath).catch(() => undefined);
+  }
